"""Editorial question designs for student supports and work pathways."""

from review_angle_plans import audit, revise_domain


STUDENT = """history_origins|A Campus Support Emerges|Which documented student need led to one support program?|Trace dated policy and student input.
famous_examples|A Student-Life Initiative Tested|What did a named service actually change?|Compare uptake, outcomes, and who was missed.
hidden_stories|Students outside the Typical Story|Whose work, care, disability, or housing needs are absent?|Use consented accounts and institutional data.
beginner_explainers|Finding Campus Support|How can a student identify eligibility and current access?|Map one institution's official channels.
advanced_concepts|Belonging and Resources|How do material needs and social participation interact?|Separate correlation from intervention evidence.
mysteries_unsolved_cases|A Retention Gap|Which data could explain a difference in continuation?|Check selection, access, and missing outcomes.
technology_innovation|A Student-Support App|Did it improve connection to services?|Measure completed referrals and privacy impact.
people_personalities|Student Advocates|Who shaped one campus policy and how were students heard?|Use meeting and campaign records.
major_events|A Policy Changes Campus Life|What changed after a documented housing or fee decision?|Compare official policy and lived use.
how_it_works|Request to Support|How does a student move from need to eligibility, referral, and service?|Trace an anonymized pathway.
rise_fall|A Support Program Ends|Which funding or uptake evidence explains closure?|Use budget and service records.
then_vs_now|Campus Life across Two Periods|How did costs, access, and participation change?|Use comparable dates and groups.
future_developments|A Proposed Student Service|What data would show whether it works?|Define need, reach, and follow-up.
myths_vs_facts|All Students Have the Same Time?|How do paid work and care obligations affect participation?|Use student survey and schedule data.
documentary_stories|One Support Program's Record|How did student requests become policy and practice?|Trace dated proposals, launch, and evaluation.
concept_sequence|Campus Navigation Skills|Which steps must a new student learn before a problem occurs?|Sequence information, contact, and follow-up.
misconception|An Eligibility Assumption|Which common belief stops students seeking a service?|Compare official rules and learner response.
worked_example|Read a Support Policy|How can a student identify criteria, deadline, and appeal route?|Use a dated, public example.
retrieval_practice|Remembering Support Routes|Can students recall where to seek help later?|Use scenario-based delayed check.
feedback_design|Service Information That Helps|Does an explanation resolve a wrong assumption?|Test revised messages with students.
assessment_quality|Measuring Student Experience|Does a survey reach commuter and part-time students?|Audit sampling and nonresponse.
visual_explanation|Map of Campus Services|Does it clarify routes, hours, and access barriers?|Test with varied students.
transfer_to_new_case|Respond to a New Campus Problem|Can students apply navigation skills to another need?|Use unfamiliar scenario.
language_access|Support in Multiple Languages|Do translations preserve rights and eligibility?|Check student comprehension.
learner_variation|Different Student Constraints|How do disability, housing, care, and work vary?|Avoid a single model of student life.
source_literacy|Campus Claims versus Rules|Can students distinguish promotional copy from binding policy?|Compare dated official sources.
curriculum_tradeoff|Orientation Priorities|Which information matters most when time is limited?|Compare later navigation outcomes.
field_learner_misconceptions|Why a Student Did Not Apply|Which assumption or barrier was decisive?|Use confidential, consented evidence.
field_lesson_sequence|Orientation over Time|When should students revisit key services?|Test staged messages rather than one event.
field_assessment_design|Can Students Find Help?|Which scenario shows practical navigation?|Measure action path, not memorized acronym.
field_memory_and_recall|A Month after Orientation|Which support routes remain known?|Use delayed scenarios and feedback.
field_inclusive_learning|Support for Varied Students|Can remote, commuter, disabled, and working students use it?|Test hours, channels, and physical access.
"""

CAREERS = """history_origins|A Career Route Changes|Which training and labor-market shifts altered entry?|Use dated occupation records.
famous_examples|A Career Profile Rechecked|What does a named occupation profile actually describe?|Specify country, year, role, and data source.
hidden_stories|Workers behind a Career Image|Whose tasks or barriers are omitted from the stereotype?|Use worker accounts and job data.
beginner_explainers|Compare Two Career Paths|How do tasks, training, pay data, and entry routes differ?|Use current, comparable sources.
advanced_concepts|Projection versus Opportunity|Why does growth not guarantee an individual job?|Explain geography, openings, competition, and timing.
mysteries_unsolved_cases|A Skills Shortage Claim|Which vacancies, wages, and training data would test it?|Separate employer anecdotes from measured demand.
technology_innovation|A Career Tool Evaluated|Does an automated recommendation improve decisions?|Check data coverage, bias, and outcomes.
people_personalities|A Career Transition|What can one worker's path illustrate?|Use consent and avoid generalizing.
major_events|A Credential Rule Changes|How did a dated requirement alter access?|Check authority, jurisdiction, and applicants.
how_it_works|From Interest to Evidence|How can a learner research work, test fit, and compare routes?|Use concrete tasks and conversations.
rise_fall|An Occupation Transforms|Which tasks and employment measures changed?|Use consistent occupation definitions.
then_vs_now|Entry Paths across Time|How did training cost and hiring filters change?|Compare dated data and regions.
future_developments|A Projected Occupation|Which assumptions drive a job outlook?|Treat forecast as scenario, not promise.
myths_vs_facts|High Median Pay Means Starting Pay?|Which wage statistic is being quoted?|Read experience, location, and worker coverage.
documentary_stories|One Career Decision Trail|How did a learner evaluate options and change course?|Use consented account and source checks.
concept_sequence|Career Decision Steps|Which questions should precede choosing a credential?|Sequence tasks, requirements, cost, and alternatives.
misconception|A Single Best Career?|How do values and constraints change fit?|Compare plausible learner situations.
worked_example|Read an Occupation Profile|How can a student identify duties, entry path, pay, and outlook?|Use a dated BLS page and limitations.
retrieval_practice|Career Source Recall|Can learners later find trustworthy occupation data?|Use new occupation scenario.
feedback_design|Correct a Career Assumption|Which feedback points to the relevant data?|Test revised choice rationale.
assessment_quality|Is a Career Quiz Valid?|What outcome does a recommendation instrument predict?|Examine validation and fairness.
visual_explanation|Route Map to a Role|Does a diagram show credential costs and alternatives?|Check local accuracy and accessibility.
transfer_to_new_case|Research an Unfamiliar Occupation|Can a learner apply the same evidence checklist?|Assess source and comparison quality.
language_access|Career Advice across Languages|Can learners understand role and credential terminology?|Test translated resources.
learner_variation|Different Starting Positions|How do time, money, location, and care shape pathways?|Avoid assuming one route.
source_literacy|Job Ad versus Occupation Data|What does each source tell us and omit?|Compare an actual ad with official statistics.
curriculum_tradeoff|Breadth of Exploration|How many roles can be examined well in limited time?|Measure decision reasoning.
field_learner_misconceptions|Why This Career Claim?|Which mistaken inference led to a choice?|Listen before correcting.
field_lesson_sequence|Explore, Test, Revisit|When should a learner compare work and training evidence?|Pilot staged decisions.
field_assessment_design|A Defensible Career Comparison|Can students justify a choice under stated constraints?|Use rubric for evidence and alternatives.
field_memory_and_recall|Recheck a Choice Later|Can learners update plans when data change?|Use delayed scenario.
field_inclusive_learning|Accessible Career Exploration|Can varied learners access shadowing and advice?|Check transport, disability, language, and cost.
"""

FREELANCE = """history_origins|A Freelance Market Emerges|Which technology and contracting practices shaped one sector?|Trace dated platform and labor records.
famous_examples|A Freelance Work Arrangement|What do contract, work, and payment records show?|Specify occupation, platform or direct client, place, and date.
hidden_stories|Unpaid Work behind a Project|Which pitching, revision, and administration time is omitted?|Use worker diaries and contracts.
beginner_explainers|Freelance Work Flow|How do lead, scope, agreement, delivery, invoice, and payment connect?|Follow a consented, anonymized project.
advanced_concepts|Effective Earnings|How do unpaid hours, fees, taxes, and gaps alter headline rates?|Use a transparent example, no personal advice.
mysteries_unsolved_cases|A Missing Payment|Which contract and platform records explain a disputed invoice?|Separate allegation and documented remedy.
technology_innovation|A Freelance Platform Feature|Did a tool improve matching, pay, or worker control?|Compare data and worker accounts.
people_personalities|A Freelancer's Career Path|What does one worker's transition reveal about supports?|Use consent and avoid generalizing.
major_events|A Worker-Status Rule Changes|Which date and jurisdiction changed legal treatment?|Use current official source and affected cases.
how_it_works|Negotiating Scope|How are deliverables, revisions, deadlines, and rights defined?|Examine a redacted agreement.
rise_fall|A Freelance Market Shifts|Which demand, fees, and platform rules changed?|Compare dated data and occupations.
then_vs_now|Freelance Work across Periods|How did client finding and payment risk change?|Use comparable worker samples.
future_developments|A Proposed Platform Policy|Who might gain or lose?|Treat outcomes as conditional.
myths_vs_facts|Flexible Means Secure?|How do schedule autonomy and income volatility coexist?|Use worker surveys and contract evidence.
documentary_stories|One Project's Paper Trail|How did a brief become accepted work and payment?|Trace scope, revisions, invoice, and dispute if any.
lived_experience|A Week of Freelance Work|What mix of paid and unpaid tasks occurs?|Use consented diary and context.
institutional_pathway|Routes to Support|Which professional association, agency, or legal channel exists?|Name jurisdiction and current eligibility.
incentives_norms|Ratings and Repeat Work|How do client feedback and platform rankings shape choices?|Use published rules and worker reports.
access_and_exclusion|Who Gets Seen by Clients?|Which language, location, disability, or network barriers appear?|Compare worker and platform data.
community_variation|Direct Clients versus Platforms|How do terms and control differ?|Compare similar work in two settings.
policy_in_practice|Contractor Classification|How is a legal standard applied in documented cases?|Name jurisdiction and date; avoid individual legal advice.
survey_vs_story|One Success Story and the Data|How representative is a high-income anecdote?|Check sampling and income distribution.
power_and_voice|Who Sets Project Terms?|Can workers negotiate fees, revisions, and dispute resolution?|Compare actual agreements.
unintended_consequence|A Platform Fee Change|How did a rule meant to improve matching affect earnings?|Use before-and-after worker evidence.
comparative_setting|Same Skill in Two Markets|How do payment, protection, and demand differ?|Match occupation and period.
change_over_time|Income across a Year|How variable are hours and payments?|Use anonymized longitudinal records.
ethical_dilemma|Credit and Client Confidentiality|How can a worker show work without breaching terms?|Study consented examples and agreements.
field_skill_signals|Portfolio as Evidence|Which work samples actually predict a client's task?|Check authorship, context, and outcomes.
field_hiring_filters|Client Selection|Which filters screen out capable workers?|Audit job posts and platform criteria.
field_workplace_power|Revision Requests|When do extra requests change the negotiated scope?|Use contract and communication record.
field_career_transitions|Freelance to Other Work|What skills and supports transfer?|Compare documented transitions.
field_worker_support|Protection during Gaps|Which benefits, associations, or public supports are available?|Check current jurisdiction and eligibility.
"""


if __name__ == "__main__":
    revise_domain("454", "454_student_life", STUDENT,
                  "Student life through real access to housing, food, time, campus services, participation, and student-led policy change.",
                  "dated institutional policies and service records, US education basic-needs research, anonymized student surveys, consented accounts, and outcome evaluations",
                  "Name institution, student group, policy date, and eligibility. Do not treat one student's story as typical or promotional service descriptions as proof of access.")
    revise_domain("455", "455_career_guidance", CAREERS,
                  "Career guidance through occupation tasks, training routes, realistic cost, location, labor-market evidence, and individual constraints.",
                  "current BLS occupation and wage data, local labor-market and credential rules, job advertisements, worker interviews, and guidance evaluations",
                  "Name occupation, country, region, and date. National projections and median wages are population statistics, not individual offers or guaranteed careers.")
    revise_domain("456", "456_freelancing", FREELANCE,
                  "Freelancing through contracts, paid and unpaid work, client and platform power, income variation, rights, and support systems.",
                  "redacted agreements and invoices, worker diaries, ILO platform-work surveys, current labor-agency guidance, platform terms, and dispute records",
                  "Name work type, jurisdiction, platform or direct client, and period. Worker classification and tax obligations are time- and place-specific; avoid personal legal or financial advice.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
